	internal class _Anon_ArchiveManagerListener_2 : ArchiveManagerListener
	{

			/* @Override */
			public void archiveClosed(PersistentDataTypeArchive archive) {
				editorManager.dismissEditors(archive.getDataTypeManager());
				tool.setConfigChanged(true);
				if (archive is ProjectDataTypeArchive projectArchive) {
					projectArchive.removeListener(this);
				}
				provider.archiveClosed(archive);
			}

			/* @Override */
			public void archiveOpened(PersistentDataTypeArchive archive) {
				tool.setConfigChanged(true);
				if (archive is FileDataTypeArchive fileArchive) {
					addRecentlyOpenedArchiveFile(fileArchive.getFile());
				}
				else if (archive is ProjectDataTypeArchive projectArchive) {
					projectArchive.addListener(this);
					addRecentlyOpenedProjectArchive(projectArchive);
				}
			}

